{
  "flashcards": [
    {
      "front": "What is the primary benefit of using TypeScript interfaces over types for public APIs?",
      "back": "Interfaces are generally preferred for public APIs because they are more extensible via declaration merging, allowing consumers to extend your types without modifying the original source code.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "How do you explain the difference between WCAG 'Perceivable' and 'Operable' principles?",
      "back": "Perceivable means information and UI components must be presentable to users in ways they can perceive (e.g., alt text for images). Operable means UI components and navigation must be usable by all, including keyboard-only users.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "What is the primary purpose of a design system in a large-scale React application?",
      "back": "It establishes a single source of truth for UI patterns, tokens, and components, ensuring visual consistency, reducing technical debt, and speeding up development across multiple teams.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "When building a component library, why is 'composition over configuration' preferred?",
      "back": "Composition allows components to be flexible and reusable by passing children or render props, rather than creating massive 'God components' with endless boolean props that are hard to maintain.",
      "requirement_ids": ["r5"]
    },
    {
      "front": "What is the main advantage of using Next.js Server Components for data fetching?",
      "back": "They allow you to fetch data directly on the server, reducing the amount of JavaScript sent to the client and eliminating the need for client-side 'useEffect' data fetching patterns.",
      "requirement_ids": ["r7"]
    },
    {
      "front": "What is the core philosophy of React Testing Library regarding test implementation?",
      "back": "Tests should resemble how users interact with your software. It discourages testing implementation details (like state or internal methods) and encourages testing DOM output and user behavior.",
      "requirement_ids": ["r8"]
    },
    {
      "front": "How does Playwright differ from Jest/Testing Library in terms of scope?",
      "back": "Playwright is an end-to-end testing framework that runs tests in real browsers, simulating full user flows across pages, whereas Testing Library is typically used for unit or integration testing components in isolation.",
      "requirement_ids": ["r9"]
    },
    {
      "front": "How do you handle design handoffs when a design file is missing a specific state?",
      "back": "Proactively ask the designer for clarification on edge cases (loading, error, empty, or overflow states) rather than assuming, to ensure the implementation matches the intended user experience.",
      "requirement_ids": ["r6"]
    },
    {
      "front": "What is the 'React way' to handle global state versus local state?",
      "back": "Keep state as local as possible. Only lift state up or use global state (Context, Redux, Zustand) when multiple components distant in the tree need access to the same data.",
      "requirement_ids": ["r1"]
    },
    {
      "front": "What is the difference between 'aria-label' and 'aria-labelledby'?",
      "back": "aria-label provides a string label for an element. aria-labelledby references the ID of another element on the page to use as the label, which is better for dynamic or existing text.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "Why should you avoid using 'any' in TypeScript?",
      "back": "It disables type checking for that variable, effectively bypassing the safety TypeScript provides. It leads to runtime errors that are hard to debug and defeats the purpose of using TypeScript.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "What is a 'Design Token' in the context of a design system?",
      "back": "Design tokens are the atomic building blocks of a design system—variables for colors, spacing, typography, and shadows—that ensure consistency across different platforms (Web, iOS, Android).",
      "requirement_ids": ["r4"]
    },
    {
      "front": "How do you ensure your component library remains accessible?",
      "back": "Use semantic HTML elements, manage focus states correctly, ensure keyboard navigability, and include appropriate ARIA attributes where semantic HTML is insufficient.",
      "requirement_ids": ["r3", "r5"]
    },
    {
      "front": "What is the benefit of using 'Next.js' for SEO in a React application?",
      "back": "Next.js supports Server-Side Rendering (SSR) and Static Site Generation (SSG), which deliver fully rendered HTML to the browser, making it significantly easier for search engine crawlers to index content.",
      "requirement_ids": ["r7"]
    }
  ]
}
